
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_hyb_gga_xc_mb3lyp_rc04_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("hyb_gga_xc_mb3lyp_rc04", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-3.537257030489398e+00, -3.471490697367473e+00, -3.379384251467126e+00, -3.251893403761500e+00, -3.078375740399665e+00, -2.847853296453335e+00, -2.551967614891922e+00, -2.190191305222948e+00, -1.776352218596617e+00, -1.340121273168142e+00, -9.114586461868039e-01, -6.189142062923716e-01, -5.349458965556966e-01, -4.476442172667638e-01, -3.278993690974691e-01, -2.077100354586595e-01, -1.207285926967612e-01, -7.425252971688824e-02, -4.491201853690939e-02, -3.013860576597874e-02]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


